/**
 * Wave 3 (21 Nov 2026) corrections to a generated record, so the generated blocks stay as their builds write them: a
 * company wave 2 knew by name only (its site answered a bot check on 20 Nov) whose own careers board the wave-3 research
 * opened on 21 Nov (research/wave3/new-careers.json: its two postings in the app were read there).
 */
const CORRECTIONS: Readonly<Partial<Record<CompanyId, Pick<Company, "careersUrl" | "source" | "checkedAt" | "note">>>> = {
  "riyadh-air": {
    careersUrl: "https://careers-riyadhair.icims.com/jobs",
    source: "careers-page",
    checkedAt: CHECKED_WAVE3,
    note: "wave 3 (research/wave3/new-careers.json): its iCIMS careers board opened on 21 Nov 2026 (two postings in the app); on 20 Nov its own site answered a bot check (not verified then)",
  },
};

export const COMPANIES: readonly Company[] = COMPANY_RECORDS.map((c) => {
  const fix = CORRECTIONS[c.id];
  return fix ? { ...c, ...fix } : c;
});

